DROP TRIGGER SMART.AFTER_INC_ACCOUNT;

CREATE OR REPLACE TRIGGER AFTER_INC_ACCOUNT
 AFTER 
 INSERT
 ON ACCOUNT
 REFERENCING OLD AS OLD NEW AS NEW
 FOR EACH ROW 
DECLARE
  cursor dats is (select distinct dat from operkurs where dat>=:new.open_dat);
  I INTEGER;
  nw INTEGER;
  CurrentDate DATE;
 	PrevDate DATE;
 	
BEGIN
  SELECT tr_seg_account.CURRVAL INTO nw FROM dual;
  SELECT Tek_dat, Pred_Dat INTO CurrentDate, PrevDate FROM sysdat;

if :new.open_dat <> CurrentDate then
for Adat in dats loop   
  sbop.add_archost(nw, adat.dat);
end loop;
else
  sbop.add_archost(nw, CurrentDate);
  sbop.add_archost(nw, PrevDate);
end if;

END After_Inc_Account;
/

DROP TRIGGER SMART.BEFOR_INC_ACCOUNT;

CREATE OR REPLACE TRIGGER "SMART".befor_inc_account
BEFORE INSERT 
ON account
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
BEGIN
   SELECT tr_seg_account.NEXTVAL
     INTO :NEW.id
     FROM dual;
	:new.OP_ID := sblogin.UserID;
END befor_inc_account;
/

DROP TRIGGER SMART.BU_ACCOUNT_RESTRICT_UPDATE;

CREATE OR REPLACE TRIGGER "SMART".bu_account_restrict_update
BEFORE UPDATE 
ON account
REFERENCING NEW AS NEW OLD AS OLD
FOR EACH ROW
begin
  if (:NEW.VAL_ACC <> :OLD.VAL_ACC) or (:NEW.ACC_NO <> :OLD.ACC_NO) then 
  raise_application_error(-20034,'Editing Account Currency or Account Number Restricted by system');
	end if;
end;
/



